public class DatetimeNullSearchProbe62 {
    public static Map<String,Object> observe(String row) {
        Map<String,Object> out = new Map<String,Object>{'row'=>row, 'isTest'=>Test.isRunningTest()};
        String phase = 'setup';
        try {
            Datetime cutoff = Datetime.newInstanceGmt(2020,1,2,0,0,0);
            Datetime emptyCutoff;
            List<SearchMoment__c> seed = new List<SearchMoment__c>{
                new SearchMoment__c(Name='ABlank'),
                new SearchMoment__c(Name='BEarly', RecordedAt__c=cutoff.addDays(-1)),
                new SearchMoment__c(Name='CEqual', RecordedAt__c=cutoff),
                new SearchMoment__c(Name='DLate', RecordedAt__c=cutoff.addDays(1))
            };
            Database.insert(seed, true, AccessLevel.SYSTEM_MODE);
            phase = 'fixedCandidates';
            if (row != 'D16') Test.setFixedSearchResults(new List<Id>{seed[3].Id,seed[0].Id,seed[1].Id,seed[2].Id});
            String predicate;
        if (row == 'D01') predicate = 'RecordedAt__c > :cutoff';
        else if (row == 'D02') predicate = 'RecordedAt__c >= :cutoff';
        else if (row == 'D03') predicate = 'RecordedAt__c < :cutoff';
        else if (row == 'D04') predicate = 'RecordedAt__c <= :cutoff';
        else if (row == 'D05') predicate = 'NOT (RecordedAt__c > :cutoff)';
        else if (row == 'D06') predicate = 'NOT (RecordedAt__c >= :cutoff)';
        else if (row == 'D07') predicate = 'NOT (RecordedAt__c < :cutoff)';
        else if (row == 'D08') predicate = 'NOT (RecordedAt__c <= :cutoff)';
        else if (row == 'D09') predicate = 'RecordedAt__c = null';
        else if (row == 'D10') predicate = 'RecordedAt__c != null';
        else if (row == 'D11') predicate = 'RecordedAt__c > :cutoff OR Name = \'ABlank\'';
        else if (row == 'D12') predicate = 'NOT (RecordedAt__c > :cutoff OR Name = \'ABlank\')';
        else if (row == 'D13') predicate = 'RecordedAt__c > :cutoff AND Name = \'ABlank\'';
        else if (row == 'D14') predicate = 'NOT (RecordedAt__c > :cutoff AND Name = \'DLate\')';
        else if (row == 'D15') predicate = 'RecordedAt__c != null';
        else if (row == 'D16') predicate = 'RecordedAt__c > :cutoff';
        else if (row == 'D17') predicate = 'RecordedAt__c > null';
        else if (row == 'D18') predicate = 'RecordedAt__c > :emptyCutoff';
        else if (row == 'Q01') predicate = 'NOT (RecordedAt__c > :cutoff)';
            String orderBy = row == 'D15' ? 'RecordedAt__c DESC' : 'Name ASC';
            phase = 'query';
            List<String> labels = new List<String>();
            String exceptionType;
            String message;
            try {
                List<SObject> found;
                if (row == 'Q01') found = Database.query('SELECT Name FROM SearchMoment__c WHERE '+predicate+' ORDER BY '+orderBy, AccessLevel.SYSTEM_MODE);
                else found = Search.query('FIND {unindexedneedle} IN NAME FIELDS RETURNING SearchMoment__c(Name WHERE '+predicate+' ORDER BY '+orderBy+')', AccessLevel.SYSTEM_MODE)[0];
                for (SObject record : found) labels.add((String)record.get('Name'));
            } catch (Exception e) { exceptionType=e.getTypeName(); message=e.getMessage(); }
            out.put('labels', labels); out.put('exceptionType', exceptionType); out.put('message', message);
        } catch (Exception e) { out.put('outerExceptionType',e.getTypeName()); out.put('outerMessage',e.getMessage()); }
        out.put('phase', phase);
        return out;
    }
}

